"""
    @renamed old new

Define `old` as a deprecated spelling of `new`.

The generated method forwards every argument and keyword argument, and warns once
per call site. The warning goes through `@warn` rather than `Base.depwarn`, so it
is printed whatever `--depwarn` is set to.
"""
macro renamed(old, new)
    msg = "$old is deprecated, use $new"
    return quote
        function $(esc(old))(args...; kwargs...)
            @warn $msg maxlog = 1
            return $(esc(new))(args...; kwargs...)
        end
    end
end

